pattern:
echo "=== (a) live stream ===" curl -sS --max-time 30 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"ok","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/a.txt -w "http=%{http_code} t=%{time_total}
" echo "events:" grep -o '^event: [a-z_]*' /tmp/opencode/shimtest/a.txt sort uniq -c echo "delta texts:" grep -o 'LIVE_\|DELTA' /tmp/opencode/shimtest/a.txt tr '
' ' ' echo echo "=== (d) regression fallback ===" curl -sS --max-time 30 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"regress","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/d.txt -w "http=%{http_code} t=%{time_total}
" echo "events:" grep -o '^event: [a-z_]*' /tmp/opencode/shimtest/d.txt sort uniq -c echo "FALLBACK present:" grep -c FALLBACK_TEXT /tmp/opencode/shimtest/d.txt echo "=== non-stream passthrough ===" curl -sS --max-time 30 -X POST $B -H 'content-type: application/json' --data-binary '{"model":"ok","max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/ns.txt -w "http=%{http_code} t=%{time_total}
" echo "=== OpenAI facade ===" curl -sS --max-time 30 -X POST http://127.0.0.1:8784/v1/chat/completions -H 'content-type: application/json' --data-binary '{"model":"ok","max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/f.json -w "http=%{http_code} t=%{time_total}
" echo "=== (c) hang retry ===" curl -sS --max-time 40 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"hang","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/c.txt -w "http=%{http_code} t=%{time_total}
" echo "events:" grep -o '^event: [a-z_]*' /tmp/opencode/shimtest/c.txt sort uniq -c echo "--- shim3 journal ---" cat /tmp/opencode/shimtest/shim3.log
